#define FIRST_LED 0

/* The STM32H750B-DK board implementation provides these symbols, but the
 * current board Kconfig does not select CONFIG_ARCH_HAVE_LEDS, so
 * <nuttx/board.h> may hide the prototypes from application code.
 */

#ifndef CONFIG_ARCH_HAVE_LEDS
uint32_t board_userled_initialize(void);
void board_userled(int led, bool ledon);
#endif

int main(int argc, char *argv[])
{
  uint32_t nleds = board_userled_initialize();

  if (nleds == 0)
    {
      printf("first_led: no user LEDs available\n");
      return 1;
    }

  printf("first_led: blink LED %d, total LEDs: %lu\n",
         FIRST_LED, (unsigned long)nleds);

  for (int i = 0; i < 5; i++)
    {
      board_userled(FIRST_LED, true);
      usleep(500 * 1000);

      board_userled(FIRST_LED, false);
      usleep(500 * 1000);
    }

  board_userled(FIRST_LED, true);
  printf("first_led: LED %d left ON\n", FIRST_LED);

  return 0;
}
